    function testFuzz_property(uint256 amount, uint64 delta) public {
        amount = bound(amount, 0, 1000 ether);
        delta = uint64(bound(delta, 1, type(uint64).max / 2));
        address actor = address(0xABE1);
        vm.deal(actor, amount);
        vm.warp(block.timestamp + delta);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok == (amount == 10 ether));
